export function atlasZh(value) {
 if (typeof value !== 'string') return value;
 let s=value;
 const esc = x => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
 for (const [en,zh] of pairs) s=s.replace(new RegExp('\\b'+esc(en)+'\\b','gi'),zh);
 s=s.replace(/\b(The|A|An)\s+/g,'').replace(/\b(of|the|and)\b/gi,'');
 const extras = [["round","绕"],["N end","N 极处"],["centre","中心"],["center","中心"],["heading","方向角"],["toward","朝向"],["towards","朝向"],["same","相同"],["neutral","中性"],["ions","离子"],["ion","离子"],["one electron","一个电子"],["electron","电子"],["electrons","电子"],["drift","漂移"],["cart","小车"],["ball","球"],["cork","软木"],["ice","冰"],["water","水"],["aluminium","铝"],["iron","铁"],["ground","接地"],["wall","墙"],["balloon","气球"],["like","同号"],["unlike","异号"],["charges","电荷"],["pole","磁极"],["approaching","接近"],["out","向外"],["from","从"],["to","到"]];
 s=s.replace(/\bround\s+N end\b/gi,'N 极处周围').replace(/\bat\s+centre\b/gi,'在中心').replace(/\bat\s+center\b/gi,'在中心');
 for (const [en,zh] of extras) s=s.replace(new RegExp('\\b'+esc(en)+'\\b','gi'),zh);
 s=s.replace(/相同[ 	]+体积/g,'体积相同').replace(/[ 	]{2,}/g,' ');
 return s;
}